<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
final class PaymentIntentRecord extends Model{use HasUuids;protected$table='payment_intents';protected$fillable=['tenant_id','proposal_id','provider','provider_reference','payer_phone_e164','amount_minor','currency','status','idempotency_key','provider_snapshot','requested_by','expires_at','customer_prompted_at','request_channel','journal_id','reconciled_at'];protected function casts():array{return['provider_snapshot'=>'array','expires_at'=>'datetime','customer_prompted_at'=>'datetime','reconciled_at'=>'datetime'];}public function proposal():BelongsTo{return$this->belongsTo(Proposal::class);}public function attempts():HasMany{return$this->hasMany(PaymentAttempt::class,'payment_intent_id');}}
